formData.jsFunction:
def validate(request, response = [:]) {
	def location = (request.containsKey("location") && request.location != null) ? request.location : null
	if (location == null || location.contains("metadata")) {
		response.location = "The required key 'location' is invalid in formData " + location
	}
	if (location == "") {
		response.location = "Please select a folder to save"
	}
	return response

}
